#!/usr/bin/env python3
"""Turn 35 Wave 108: THE MAXED-PLAYER REVERSION BUG, AND WHY SOME BUNDESLIGA PLAYERS ARE IN.

Wave 108's centrepieces:

1. THE MAXED-PLAYER REVERSION BUG — the most serious finding of the sweep. A player who
   locked players to observe what the December 2025 update would do to their ratings reports
   that **maxed players lost all their upgraded stats and reverted to their base ratings**,
   and that releasing a maxed player caused their rating to **downgrade to the new official
   rating**, defeating the purpose of the recovery tab. That is not an inconvenience; it is
   the destruction of coached progress, and it is the same penalty the corpus already records
   for exploits — except here the player did nothing.

2. THE RANDOM-FORFEIT AND RANDOM-MOVEMENT BUGS — the two that cost wins directly. Matches
   ending as forfeits when the player never left, and players making meaningless movements
   and failing to hold their positions. Both are reported by spenders, which matters: these
   are not edge cases on cheap devices.

3. WHY SOME BUNDESLIGA PLAYERS ARE IN THE GAME AND OTHERS ARE NOT. DLS licenses **players**
   through FIFPRO, not leagues — and Germany and Brazil are not FIFPRO-licensed. So a
   Bundesliga player appears only if his **national team** is licensed: Andre Silva is in
   because Portugal is. That is a mechanism, and it explains a roster that otherwise looks
   arbitrary.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w108')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_bug=new_ev("r/DreamLeagueSoccer 1rg2fg8 'There is a serious problem with the recent update. Walk with me' (27 Feb 2026 - the locked-player rating bug and the maxed-player stat reversion), sikayetvar.com DLS complaint feed (Apr-Jul 2026 - the dated bug reports: random forfeits, random player movement, server error despite stable internet, connection-lost auto-forfeit, iCloud save failure, Facebook restore failure, deleted account after reinstall), r/DreamLeagueSoccer 1pgj3fr (7 Dec 2025 - the DLS26 launch complaint set), r/DreamLeagueSoccer 1pe08j8 (4 Dec 2025 - the auto-switch complaint), r/DreamLeagueSoccer 1azm7t9 (the DLS24-era freeze and random-direction bug), Google Play review 14.5m reviews listing (the switching delay and exploitability), App Store review 17 Jan (tripping, ball blocked by own team, inaccurate passing, woodwork), fifaworldcupnews.com DLS26 update history (23 Jul 2026 - the per-update bug-fix list), r/DreamLeagueSoccer 10v0ia5 (6 Feb 2023 - the national-team license route with the Andre Silva example), r/DreamLeagueSoccer 1deya7d (13 Jun 2024 - Germany and Brazil are not FIFPRO-licensed), r/DreamLeagueSoccer js2204 (11 Nov 2020 - non-German Bundesliga players only), firsttouchgames official X post (24 Jan 2017 - 'due to licensing reasons we cannot include all Bundesliga players'), globeany.com (1 Oct 2026 - FIFPRO licenses players, not league packages), dlsinside.com/teams (16 Sep 2026 - the full team roster with per-club player counts)",
    "THE MAXED-PLAYER REVERSION BUG, THE RANDOM-FORFEIT AND RANDOM-MOVEMENT BUGS, AND THE LICENSING MECHANISM. (1) THE MAXED-PLAYER REVERSION BUG, the most serious finding of the sweep: a player who locked players to observe what the December 2025 update would do to their ratings reports that '**maxed players lost all their upgraded stats and reverted to their base ratings after the update**' and that '**releasing a maxed player caused their rating to downgrade to the new official rating, defeating the purpose of the recovery tab.**' The same poster notes locked players' ratings did not change at all across the update ('I locked 79 Barcola, and it was still 79'). **That is the destruction of coached progress, and it is the same penalty the corpus records for exploits - except here the player did nothing.** It is also a direct argument for the corpus's stop-coaching advice, from an unexpected direction. (2) THE RANDOM-FORFEIT BUG: 'I keep getting kicked out of Dream League Soccer matches for no reason. **The game says I forfeited even when I never left the match.** This mostly happens during live games and events, and it keeps costing me wins while the other player gets the victory.' A second report describes the mechanism: 'I suddenly receive an internet connection lost warning, the game immediately closes, and the match is auto-[forfeited].' (3) THE RANDOM-MOVEMENT BUG: 'my players are making meaningless movements on the field, failing to hold their positions, and cannot even catch opposing players who are weaker than them on paper' - from a player reporting $83-$110 of in-game purchases, so this is not a cheap-device edge case. A DLS24-era report describes the same class of fault: 'my players will freeze in place or start moving to random directions without me being able to control them.' (4) THE SERVER ERROR DESPITE STABLE INTERNET, and the iCloud and Facebook restore failures - the latter confirming the corpus's Facebook-removal finding from the complaint side. (5) THE DLS26 BUG-FIX HISTORY, which tells you which faults are already closed: **January 2026** crash fixes and performance tweaks · **May 2026** 'Resolved a known UI glitch where the game would occasionally freeze during quick substitutions in Live Multiplayer matches' · **August 2026** 'Fixed an issue causing custom team logos to render at low resolutions on certain devices, along with general frame-rate stabilization for 120Hz displays.' (6) THE USER-SENTIMENT SUMMARY, which is the corpus's first aggregate view of what players actually complain about: lost accounts and difficulty restoring progress · problems transferring save data between devices · connection and matchmaking issues · unexpected errors after updates · IAP concerns and missing items · account linking and login problems · gameplay balance and matchmaking complaints · slow support responses · performance issues on certain devices. (7) THE LICENSING MECHANISM: DLS licenses **players** through FIFPRO, not league packages - 'FTG operates primarily under a FIFPRO license, they license individual player names and likenesses rather than complete league packages' - and '**Germany (and Brazil) are NOT licensed by FIFPro, so their leagues can't be included.**' **So a Bundesliga player appears only if his NATIONAL TEAM is licensed**: 'Andre Silva plays in RB Leipzig but is available in DLS because DLS has the license of Portugal national team.' FTG's own account states it plainly: 'due to licensing reasons we cannot include all Bundesliga players.' (8) THE FULL TEAM ROSTER with per-club player counts (dlsinside): A Bergamo 29, A Bilbao 36, A Madrid 34, A Milan 30, Aberdeen 28, African Allstars 31, Ajaccio 16, Ajax 30, Alaves 27, Alkmaar 31, Allstar XI 16, Almere 19 - a recruitment resource alongside the player database. (9) THE COMPLAINT SET from the DLS26 launch: 'the goal does not feel they're in the game, the B shots is overpowered and defence isn't what it used to be' · 'players with more than 90 in speed and acceleration frequently lose in the race to bronze players' · 'defender with 80+ strength and 189cm+ got outplay in aerial duel by a player that is slightly better in stats' · and from a store review: 'they trip players all the time... Passing is not accurate, the bots pick up before my player gets it... at least 3 shots hit the post and bounce back.'",
    "THE MAXED-PLAYER REVERSION BUG: maxed players lost all upgraded stats and reverted to base ratings after the December 2025 update, and releasing a maxed player downgraded them to the new official rating - destroying coached progress for a player who did nothing wrong. THE RANDOM-FORFEIT BUG: matches ending as forfeits when the player never left, with the mechanism being a connection-lost warning that closes the game. THE RANDOM-MOVEMENT BUG: players making meaningless movements and failing to hold positions, reported by spenders. THE DLS26 BUG-FIX HISTORY (Jan 2026 crashes, May 2026 UI freeze on quick subs, Aug 2026 logo resolution and 120Hz). THE USER-SENTIMENT SUMMARY of complaint categories. AND THE LICENSING MECHANISM: DLS licenses PLAYERS through FIFPRO not leagues, Germany and Brazil are not FIFPRO-licensed, so a Bundesliga player appears only if his national team is licensed.",
    "THE MAXED-PLAYER REVERSION BUG, AND WHY SOME BUNDESLIGA PLAYERS ARE IN",
    quality="community")

add_claim("⚠️ THE MAXED-PLAYER REVERSION BUG: '**maxed players lost all their upgraded stats and reverted to their base ratings after the update**' - reported by a player who had deliberately locked players to observe what the December 2025 update would do to their ratings. **That is the destruction of coached progress, and it is the same penalty the corpus records for exploits - except here the player did nothing.** It is also an unexpected argument for the corpus's stop-coaching advice.", 3, "bugs/maxed-player-stat-reversion", [e_bug], notes="The most serious finding of the sweep")
add_claim("⚠️ THE LOCKED-PLAYER RATING BUG, and its consequence: '**releasing a maxed player caused their rating to downgrade to the new official rating, defeating the purpose of the recovery tab.**' The same poster notes locked players' ratings did not change at all across the update - 'I locked 79 Barcola, and it was still 79 when I had it updated.' **So the Lock feature did not protect ratings across the DLS26 update, and releasing a maxed player undid the max.**", 3, "bugs/locked-player-ratings-unchanged", [e_bug])
add_claim("⚠️ THE RANDOM-FORFEIT BUG: 'I keep getting kicked out of Dream League Soccer matches for no reason. **The game says I forfeited even when I never left the match.** This mostly happens during live games and events, and it keeps costing me wins while the other player gets the victory.' A second report gives the mechanism: 'I suddenly receive an **internet connection lost** warning, the game immediately closes, and the match is auto-[forfeited].'", 3, "bugs/random-forfeit", [e_bug])
add_claim("⚠️ THE RANDOM-MOVEMENT BUG: 'my players are making **meaningless movements** on the field, **failing to hold their positions**, and cannot even catch opposing players who are weaker than them on paper' - reported by a player citing $83-$110 of in-game purchases, so this is not a cheap-device edge case. A DLS24-era report describes the same class of fault: 'my players will **freeze in place or start moving to random directions** without me being able to control them.'", 3, "bugs/random-player-movement", [e_bug])
add_claim("THE SERVER ERROR DESPITE STABLE INTERNET is a documented complaint category: 'For the past two days, I have been consistently receiving a DLS server error on the DLS app on my Android device... Despite having no issues with my internet connection, this error is preventing me from logging into the game entirely.'", 3, "bugs/server-error-stable-connection", [e_bug])
add_claim("THE DLS26 BUG-FIX HISTORY, which tells you which faults are already closed: **January 2026** crash fixes and performance tweaks · **May 2026** 'Resolved a known UI glitch where the game would occasionally **freeze during quick substitutions in Live Multiplayer matches**' · **August 2026** 'Fixed an issue causing **custom team logos to render at low resolutions** on certain devices, along with general **frame-rate stabilization for 120Hz displays**.'", 3, "patching/dls26-bug-fix-history", [e_bug])
add_claim("THE USER-SENTIMENT SUMMARY, the corpus's first aggregate view of what DLS players actually complain about: lost accounts and difficulty restoring progress · problems transferring save data between devices · connection and matchmaking issues · unexpected errors after updates · IAP concerns and missing items · account linking and login problems · gameplay balance and matchmaking complaints · slow support responses · performance issues on certain devices.", 3, "bugs/user-sentiment-summary", [e_bug])
add_claim("THE LICENSING MECHANISM: DLS licenses **players** through FIFPRO, not league packages - 'FTG operates primarily under a FIFPRO license, they license **individual player names and likenesses** rather than complete league packages' - and '**Germany (and Brazil) are NOT licensed by FIFPro, so their leagues can't be included.**' **So a Bundesliga player appears only if his NATIONAL TEAM is licensed**: 'Andre Silva plays in RB Leipzig but is available in DLS because DLS has the license of Portugal national team.'", 3, "licensing/players-not-leagues", [e_bug], notes="Explains a roster that otherwise looks arbitrary")
add_claim("FTG's own account confirms the licensing gap: '@AIMASHSOBAAN Unfortunately **due to licensing reasons we cannot include all Bundesliga players**' - an official FTG statement, and the reason non-German Bundesliga players appear while German ones do not.", 2, "licensing/ftg-bundesliga-statement", [e_bug])
add_claim("THE FULL DLS26 TEAM ROSTER with per-club player counts (dlsinside, 16 Sep 2026): A Bergamo 29, A Bilbao 36, A Madrid 34, A Milan 30, Aberdeen 28, African Allstars 31, Ajaccio 16, Ajax 30, Alaves 27, Alkmaar 31, Allstar XI 16, Almere 19. A recruitment resource alongside the player database, and the numbers show squad depth varies widely by club.", 4, "licensing/team-roster-player-counts", [e_bug])
add_claim("THE DLS26 LAUNCH COMPLAINT SET, recorded so the corpus carries the negative case as well as the positive: 'the goal does not feel they're in the game, the B shots is overpowered and defence isn't what it used to be' · 'players with more than 90 in speed and acceleration frequently lose in the race to bronze players' · 'defender with 80+ strength and 189cm+ got outplay in aerial duel by a player that is slightly better in stats' · and from a store review: 'they trip players all the time... Passing is not accurate, the bots pick up before my player gets it... at least 3 shots hit the post and bounce back.'", 4, "bugs/dls26-launch-complaint-set", [e_bug])

for p in ['EV-521_maxed_player_reversion.html','EV-521b_random_forfeit_and_licensing.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
